<?php
namespace App\Http\Controllers;
use App\Models\{SalesInvoice,PurchaseInvoice,Budget,Expense}; use App\Services\BudgetTracker; use Illuminate\Support\Facades\{Http,Cache,Log};
class DashboardController extends Controller { public function __invoke(BudgetTracker $tracker){ $rates=Cache::remember('currency.rates',now()->addMinutes((int)config('services.currency.cache_ttl',60)),function(){try{return Http::timeout((int)config('services.currency.timeout',5))->get(config('services.currency.url'))->json();}catch(\Throwable $exception){Log::warning('Currency rates request failed',['url'=>config('services.currency.url'),'exception'=>get_class($exception)]);return null;}}); $budgets=Budget::with('expenses')->latest()->take(5)->get();$budgetSummaries=$budgets->mapWithKeys(fn($budget)=>[$budget->id=>$tracker->summarize($budget)]);return view('dashboard', ['sales'=>SalesInvoice::sum('total'),'purchases'=>PurchaseInvoice::sum('total'),'expenses'=>Expense::sum('amount'),'outstanding'=>SalesInvoice::whereIn('status',['Pending','Overdue'])->sum('total'),'budgets'=>$budgets,'budgetSummaries'=>$budgetSummaries,'rates'=>$rates]);} }
